//! ♻️ The fixture retirement producer keeps its actual owner and Source through paid replies.
use semio_framework_value_control_contract::*;
use semio_framework_value_retirement::{OriginalRetirementFailure,retirement::controlled::ControlledRetirement};
use semio_framework_value_testing_admission::{EffectBank,Wallet,FixtureRetirementProducer};
use semio_framework_value_testing_allocator::observe_retirement_allocations as observe;
#[test]fn borrowed_fixture_retirement_keeps_the_original_owner_and_bank(){let law:serde_json::Value=serde_json::from_str(include_str!("retirement.json")).unwrap();let mut bank=EffectBank::new(Wallet::from_profile(&law["stock"]));let mut cursor=ControlledRetirement::retain(());let mut authority=Some(OriginalEffectAuthority::new(FixtureRetirementProducer::<()>::new(&mut cursor)));let mut action=None;let mut output=None;for _ in 0..law["maximumTurns"].as_u64().unwrap(){if authority.as_ref().unwrap().producer().owner().terminal_is_empty(){break}assert!(!authority.as_ref().unwrap().producer().owner().requires_original_birth());let demand=authority.as_ref().unwrap().producer().owner().next_demand(4096).unwrap();let work=authority.as_ref().unwrap().producer().owner().next_computational_work(4096).unwrap();assert!(demand.copy_bytes<=4096);let grant=bank.loan(1,demand.copy_bytes);let mut heap_sum=(0usize,0usize);for _ in 0..law["maximumTurns"].as_u64().unwrap(){let ((poll,actual),heap)=observe(||bank.run(grant,work,|effect|{let before=effect.performed_work();let ready=authority.as_mut().unwrap().drive(&mut (4096,None),effect,&mut action).unwrap();let work=effect.performed_work()-before;if ready{RetainedWorkPoll::Complete(RetainedWorkOutcome::<(),ValueError>{result:Ok(()),work})}else{RetainedWorkPoll::Pending{work}}}));heap_sum.0+=heap.0;heap_sum.1+=heap.1;if let Some(actual)=actual{assert_eq!(actual,heap_sum.0)}if let RetainedWorkPoll::Complete(turn)=poll{turn.result.unwrap();let progress=match action.as_ref().unwrap().recorded_reply().unwrap(){Ok(step)=>step.progress(),Err(error)=>error.retained_progress()};let _=bank.take_admitted();bank.post(progress,grant,heap_sum);break}}assert!(action.as_ref().unwrap().recorded_reply().is_some());let demand=OriginalEffectAuthority::<FixtureRetirementProducer<()>>::transfer_reply_demand().unwrap();assert!(demand.copy_bytes<=4096);let grant=bank.loan(1,demand.copy_bytes);let ((poll,actual),heap)=observe(||bank.run(grant,1,|effect|{let context=(4096,None);let turn=authority.as_mut().unwrap().transfer_reply_into(&context,&mut action,&mut output,effect);RetainedWorkPoll::Complete(turn)}));let RetainedWorkPoll::Complete(turn)=poll else{panic!("reply transfer pending")};assert_eq!(actual,None);let progress=turn.result.unwrap().unwrap();let _=bank.take_admitted();bank.post(progress,grant,heap);assert!(output.as_ref().unwrap().is_ok());let demand=RetirementDemand{copy_bytes:std::mem::size_of::<Option<Result<RetainedCloneStep,OriginalRetirementFailure>>>(),depth:1,..Default::default()};assert!(demand.copy_bytes<=4096);let grant=bank.loan(1,demand.copy_bytes);let ((poll,actual),heap)=observe(||bank.run(grant,1,|effect|{assert!(effect.performed(1).unwrap());drop(output.take());RetainedWorkPoll::Complete(RetainedWorkOutcome::<RetainedCloneProgress,ValueError>{result:Ok(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()}),work:1})}));let RetainedWorkPoll::Complete(turn)=poll else{panic!("reply retirement pending")};assert_eq!(actual,None);let _=bank.take_admitted();bank.post(turn.result.unwrap(),grant,heap);}assert!(authority.as_ref().unwrap().producer().owner().terminal_is_empty());let demand=OriginalEffectAuthority::<FixtureRetirementProducer<()>>::producer_transfer_demand().unwrap();assert!(demand.copy_bytes<=4096);let grant=bank.loan(1,demand.copy_bytes);let mut producer=None;let ((poll,actual),heap)=observe(||bank.run(grant,1,|effect|{let context=(4096,None);RetainedWorkPoll::Complete(OriginalEffectAuthority::transfer_producer(&mut authority,&context,&mut producer,effect))}));let RetainedWorkPoll::Complete(turn)=poll else{panic!("producer transfer pending")};assert_eq!(actual,None);let _=bank.take_admitted();bank.post(turn.result.unwrap().unwrap(),grant,heap);let demand=RetirementDemand{copy_bytes:std::mem::size_of::<Option<FixtureRetirementProducer<()>>>(),depth:1,..Default::default()};let grant=bank.loan(1,demand.copy_bytes);let ((poll,actual),heap)=observe(||bank.run(grant,1,|effect|{assert!(effect.performed(1).unwrap());drop(producer.take());RetainedWorkPoll::Complete(RetainedWorkOutcome::<RetainedCloneProgress,ValueError>{result:Ok(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()}),work:1})}));let RetainedWorkPoll::Complete(turn)=poll else{panic!("producer retirement pending")};assert_eq!(actual,None);let _=bank.take_admitted();bank.post(turn.result.unwrap(),grant,heap);assert!(bank.is_idle());assert!(bank.into_wallet().is_ok());}
